<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import { listDevices } from '@/api/device'
import { getResourceTree } from '@/api/resource'
import { listOps } from '@/api/asset-ops'
import type { DataCenter } from '@/types/resource'
const router = useRouter(), auth = useAuthStore(), loading = ref(false), refreshed = ref('')
const tree = ref<DataCenter[]>([]), deviceTotal = ref(0), assets = ref<any[]>([]), reminders = ref<any[]>([])
const canUseAssets = computed(() => auth.user?.roles?.some(r => ['system_admin', 'asset_manager', 'asset_auditor'].includes(r.code)))
const rooms = computed(() => tree.value.flatMap(dc => dc.rooms || []))
const racks = computed(() => rooms.value.flatMap(r => r.racks || []))
const pending = computed(() => reminders.value.filter(r => !r.acknowledgedBy))
const warranty = computed(() => pending.value.filter(r => ['WARRANTY', 'PART_WARRANTY'].includes(r.kind)))
const rackAlerts = computed(() => pending.value.filter(r => r.kind === 'RACK_U'))
const cards = computed(() => [
  { label: '设备资产', value: deviceTotal.value, note: 'PC、服务器及网络等设备', icon: '▤', tone: 'blue' },
  { label: '机柜资源', value: racks.value.length, note: tree.value.length + ' 个数据中心 · ' + rooms.value.length + ' 间机房', icon: '▥', tone: 'teal' },
  { label: canUseAssets.value ? '待处理保修风险' : '机房数量', value: canUseAssets.value ? warranty.value.length : rooms.value.length, note: canUseAssets.value ? '即将过保、已过保及保障空档' : '集中维护位置与资源关系', icon: '◷', tone: 'amber' },
  { label: canUseAssets.value ? 'U 位容量告警' : '数据中心', value: canUseAssets.value ? rackAlerts.value.length : tree.value.length, note: canUseAssets.value ? '按机柜物理 U 位占用率检查' : '查看区域资源分布', icon: '▦', tone: 'purple' },
])
const distribution = computed(() => Object.entries({ PC: 'PC 终端', SERVER: '服务器', NETWORK: '网络设备', STORAGE: '存储设备', SECURITY: '安全设备', OTHER: '其他设备' }).map(([key, label]) => ({ label, value: assets.value.filter(a => (a.device.type?.category || 'OTHER') === key).length })))
const topReminders = computed(() => [...pending.value].sort((a,b) => Number(b.severity === 'DANGER') - Number(a.severity === 'DANGER')).slice(0,5))
const kindLabel = (kind: string) => ({ WARRANTY: '设备保修', PART_WARRANTY: '备件保修', RACK_U: 'U 位容量', STOCK: '备件库存', DATA: '数据完善' } as Record<string, string>)[kind] || kind
async function load() {
  loading.value = true
  try {
    const [resources, devices] = await Promise.all([getResourceTree(), listDevices({ page: 1, pageSize: 1 })])
    tree.value = resources.items || []; deviceTotal.value = devices.total || 0
    if (canUseAssets.value) [assets.value, reminders.value] = await Promise.all([listOps('devices'), listOps('reminders')])
    refreshed.value = new Date().toLocaleTimeString('zh-CN', { hour12: false })
  } catch { ElMessage.error('概览加载失败，请检查服务后刷新') } finally { loading.value = false }
}
onMounted(load)
</script>
<template>
  <div class="dashboard-page" v-loading="loading">
    <div class="page-header"><div><span class="page-kicker">WORKSPACE OVERVIEW</span><h1>运行概览</h1><p>从资产保障到机柜容量，及时掌握需要关注的变化。</p></div><div class="header-actions"><span v-if="refreshed" class="refresh-note">更新于 {{ refreshed }}</span><el-button :loading="loading" @click="load">刷新数据</el-button><el-button type="primary" @click="router.push('/room-screen')">打开机房大屏 ↗</el-button></div></div>
    <div class="overview-metrics"><el-card v-for="card in cards" :key="card.label" shadow="never"><div class="metric-top"><span>{{ card.label }}</span><span class="metric-icon" :class="card.tone">{{ card.icon }}</span></div><strong class="metric-value">{{ card.value.toLocaleString() }}</strong><p>{{ card.note }}</p></el-card></div>
    <div class="overview-grid">
      <el-card shadow="never" class="attention-panel"><template #header><div class="panel-heading"><div><h2>待办与风险</h2><p>优先查看需要处理的资产与机柜提醒</p></div><el-tag v-if="canUseAssets" type="warning" effect="light">{{ pending.length }} 项待关注</el-tag></div></template>
        <template v-if="canUseAssets"><div v-for="item in topReminders" :key="item.id" class="risk-row"><span class="risk-dot" :class="{ danger: item.severity === 'DANGER' }"/><div><strong>{{ item.title }}</strong><p>{{ item.detail }}</p></div><el-tag :type="item.severity === 'DANGER' ? 'danger' : 'warning'" effect="plain">{{ kindLabel(item.kind) }}</el-tag></div><el-empty v-if="!topReminders.length" description="暂无待处理提醒" :image-size="80"/><div class="panel-bottom"><span>告警每 15 分钟自动检查，记录处理后停止外部提醒</span><el-button link type="primary" @click="router.push('/asset-reminders')">查看提醒中心 →</el-button></div></template>
        <el-empty v-else description="资产风险详情需资产管理或审计权限" :image-size="85"/>
      </el-card>
      <el-card shadow="never" class="quick-panel"><template #header><div class="panel-heading"><div><h2>常用操作</h2><p>进入日常资产工作流程</p></div></div></template><div class="quick-links"><button @click="router.push('/devices')"><span class="quick-icon">＋</span><span><strong>设备建档</strong><small>登记设备身份、SN 与规格</small></span><b>↗</b></button><template v-if="canUseAssets"><button @click="router.push('/asset-checks')"><span class="quick-icon">▣</span><span><strong>扫码盘点</strong><small>核对实物、配置与位置差异</small></span><b>↗</b></button><button @click="router.push('/spare-parts')"><span class="quick-icon">▧</span><span><strong>备件库存</strong><small>查询各机房备件与出入库</small></span><b>↗</b></button></template><button v-if="auth.isAdmin" @click="router.push('/notification-settings')"><span class="quick-icon">♧</span><span><strong>配置告警通知</strong><small>邮件、企微与容量阈值</small></span><b>↗</b></button><button v-else @click="router.push('/data-centers')"><span class="quick-icon">▦</span><span><strong>区域与机房</strong><small>查看基础资源分布</small></span><b>↗</b></button></div></el-card>
    </div>
    <div class="overview-grid bottom-grid"><el-card shadow="never"><template #header><div class="panel-heading"><div><h2>设备分类</h2><p>按固定 IT 资产类型查看设备构成</p></div><el-button v-if="canUseAssets" link type="primary" @click="router.push('/asset-operations')">配置与保修 →</el-button></div></template><div v-if="canUseAssets" class="distribution-list"><div v-for="(item,index) in distribution" :key="item.label"><span>{{ item.label }}</span><div class="distribution-track"><i :style="{ width: (assets.length ? item.value / assets.length * 100 : 0) + '%', opacity: 1 - index * .09 }"/></div><b>{{ item.value }}</b></div></div><el-empty v-else description="设备分类统计需资产管理或审计权限" :image-size="70"/></el-card><el-card shadow="never"><template #header><div class="panel-heading"><div><h2>机房资源</h2><p>数据中心与机柜容量分布</p></div><el-button link type="primary" @click="router.push('/racks')">机柜管理 →</el-button></div></template><div class="resource-summary"><div><strong>{{ rooms.length }}</strong><span>机房</span></div><div><strong>{{ racks.length }}</strong><span>机柜</span></div><div><strong>{{ racks.reduce((sum,r) => sum + r.uHeight,0) }}</strong><span>机柜总容量 / U</span></div></div><div v-for="center in tree.slice(0,3)" :key="center.id" class="center-row"><span><i/>{{ center.name }}</span><small>{{ (center.rooms || []).length }} 间机房 · {{ (center.rooms || []).reduce((sum,r) => sum + (r.racks || []).length,0) }} 个机柜</small></div><p v-if="!tree.length" class="empty-resource">暂无机房资源，请在区域与机房中登记。</p></el-card></div>
  </div>
</template>
<style scoped>
