354b67}.quick-links button:hover{background:#f7faff;border-color:#b4c9e9}.quick-icon{width:33px;height:34px;border-radius:8px;background:#f0f4fb;color:#6486b9;display:grid;place-items:center;font-size:19px;flex:none}.quick-links strong{display:block;font-size:12px;font-weight:550}.quick-links small{display:block;font-size:10px;color:#8492a7;line-height:1.7;margin-top:4px}.quick-links b{margin-left:auto;color:#97abc5;font-weight:400}.bottom-grid{grid-template-columns:1fr 1fr;margin-top:24px}.distribution-list{display:grid;gap:22px;padding:4px 0}.distribution-list>div{display:flex;align-items:center;gap:18px;font-size:12px}.distribution-list>div>span{width:65px;color:#697d97;flex:none}.distribution-track{height:7px;background:#f0f3f8;border-radius:5px;flex:1;overflow:hidden}.distribution-track i{display:block;height:100%;background:#7399d5;border-radius:5px}.distribution-list b{width:36px;text-align:right;font-size:12px;font-weight:550}.resource-summary{display:grid;grid-template-columns:1fr 1fr 1.3fr;padding:0 0 23px;border-bottom:1px solid #edf0f5;margin-bottom:8px}.resource-summary div+div{border-left:1px solid #edf0f5;padding-left:22px}.resource-summary strong{display:block;font-size:26px;font-weight:550;font-variant-numeric:tabular-nums}.resource-summary span{display:block;font-size:11px;color:#8291a7;margin-top:8px}.center-row{display:flex;justify-content:space-between;gap:14px;align-items:center;padding:16px 0;border-bottom:1px solid #f0f3f7;font-size:12px;color:#5a6e88}.center-row i{display:inline-block;height:7px;width:7px;border-radius:2px;background:#a3b9d9;margin-right:9px}.center-row small{font-size:11px;color:#8292a8;line-height:1.6}.empty-resource{font-size:12px;color:#8292a8}
@media(max-width:1180px){.overview-metrics{grid-template-columns:1fr 1fr;gap:15px}.overview-grid{grid-template-columns:1fr}.bottom-grid{grid-template-columns:1fr 1fr}.quick-links{grid-template-columns:1fr 1fr}}@media(max-width:760px){.overview-metrics{gap:10px}.metric-value{font-size:29px}.metric-icon{width:27px;height:28px;font-size:17px}.metric-top{font-size:11px}.overview-grid,.bottom-grid{gap:16px;grid-template-columns:1fr}.quick-links{grid-template-columns:1fr}.risk-row{gap:8px}.panel-bottom{align-items:flex-start;flex-direction:column;gap:8px}.refresh-note{display:none}.resource-summary strong{font-size:24px}}
</style>
